import { describe, expect, it, vi } from 'vitest';
import { PREFERENCES_KEY, readPreferences, writePreferences } from './storage.ts';

function memory(text: string | null) {
  const entries = new Map<string, string>([['unrelated', 'keep me']]);
  if (text !== null) entries.set(PREFERENCES_KEY, text);
  return { entries, getItem: (key: string) => entries.get(key) ?? null,
    setItem: (key: string, value: string) => { entries.set(key, value); } };
}

describe('saved preferences', () => {
  it('restores only supported sizes and finite integer scores within the move cap', () => {
    const storage = memory(JSON.stringify({ size: 16,
      best: { 4: 8, 6: 999999, 8: -1, 10: 1.5, 12: 1000000, 14: '98', 16: 128, 3: 2 } }));
    expect(readPreferences(storage)).toEqual({ size: 16, best: { 4: 8, 6: 999999, 16: 128 } });
    expect(readPreferences(memory('{"size":5,"best":{"4":8}}'))).toEqual({ size: 4, best: { 4: 8 } });
  });
  it.each([null, '{', 'null', '[]', '1', '"oops"', '{"size":"8","best":null}'])
  ('ignores unavailable or malformed saved data %j', (text) => {
    expect(readPreferences(memory(text))).toEqual({ size: 4, best: {} });
  });
  it('catches storage read and write failures', () => {
    const storage = { getItem: () => { throw new Error('Unavailable'); },
      setItem: () => { throw new Error('Full'); } };
    expect(readPreferences(storage)).toEqual({ size: 4, best: {} });
    expect(readPreferences(null)).toEqual({ size: 4, best: {} });
    expect(() => writePreferences({ size: 8, best: { 8: 32 } }, storage)).not.toThrow();
  });
  it('writes only the game preference key and keeps progress out of storage', () => {
    const storage = memory(null);
    const write = vi.spyOn(storage, 'setItem');
    writePreferences({ size: 6, best: { 4: 8 } }, storage);
    expect(write).toHaveBeenCalledOnce();
    expect(storage.entries.get('unrelated')).toBe('keep me');
    expect(storage.entries.get(PREFERENCES_KEY)).toBe('{"size":6,"best":{"4":8}}');
  });
});
import { describe, expect, it } from 'vitest';
import { faceIdentity } from './faceIdentity.ts';

describe('face identity', () => {
  it('names the documented first solid and outline faces', () => {
    expect(faceIdentity(0).name).toBe('cyan solid circle, marker top');
    expect(faceIdentity(64).name).toBe('cyan outline circle, marker top');
    expect(faceIdentity(127).name).toBe('ice outline chevron, marker top-left');
    expect(faceIdentity(9).name).toBe('magenta solid square, marker top-right');
  });
  it('gives all128 faces unique non-color identities and normalized markers', () => {
    const faces = Array.from({ length: 128 }, (_, index) => faceIdentity(index));
    expect(new Set(faces.map((face) => face.name.replace(/^\w+ /, ''))).size).toBe(128);
    for (const face of faces) {
      expect(Math.hypot(face.markerX - 50, face.markerY - 50)).toBeCloseTo(40, 10);
    }
    expect(faceIdentity(9).markerX).toBeCloseTo(78.2842712475);
    expect(faceIdentity(9).markerY).toBeCloseTo(21.7157287525);
    expect(faceIdentity(32).markerY).toBe(90);
  });
  it.each([-1, 128, 1.5, NaN])('rejects invalid face %s', (id) => {
    expect(() => faceIdentity(id)).toThrow('Invalid face');
  });
});
import { describe, expect, it } from 'vitest';
import { moveFocus } from './navigation.ts';

describe('board arrow movement', () => {
  it.each([
    [0, 'ArrowLeft', 0], [0, 'ArrowUp', 0], [3, 'ArrowRight', 3], [12, 'ArrowDown', 12],
    [5, 'ArrowLeft', 4], [5, 'ArrowRight', 6], [5, 'ArrowUp', 1], [5, 'ArrowDown', 9],
  ])('moves from %i with %s to %i without wrapping', (index, key, destination) => {
    expect(moveFocus(Number(index), 4, String(key))).toBe(destination);
  });
  it.each(['Tab', 'Home', 'End', 'a', 'PageDown', 'Escape'])('leaves %s to the browser', (key) => {
    expect(moveFocus(5, 4, key)).toBeNull();
  });
  it('reaches the final row and column on a sixteen-column board', () => {
    expect(moveFocus(239, 16, 'ArrowDown')).toBe(255);
    expect(moveFocus(255, 16, 'ArrowRight')).toBe(255);
    expect(moveFocus(255, 16, 'ArrowDown')).toBe(255);
  });
});
import { describe, expect, it } from 'vitest';
import { activateCard } from '../activateCard.ts';
import { createGame } from '../state.ts';
import { turnAnnouncement } from './turnAnnouncement.ts';

describe('turn announcements', () => {
  it('emits no result for a first card or ignored action', () => {
    const initial = createGame('np1-4-1');
    if (!initial) throw new Error('Invalid fixture');
    const one = activateCard(initial, 0);
    expect(turnAnnouncement(initial, one)).toBeNull();
    expect(turnAnnouncement(one, activateCard(one, 0))).toBeNull();
  });
  it('uses the exact first match and miss messages', () => {
    const initial = createGame('np1-4-1');
    if (!initial) throw new Error('Invalid fixture');
    const one = activateCard(initial, 0);
    expect(turnAnnouncement(one, activateCard(one, 11))).toBe('Pair found. 1 pair matched.');
    expect(turnAnnouncement(one, activateCard(one, 1))).toBe('No match. Cards close after a short pause.');
  });
  it('combines the final match and win into one result', () => {
    const initial = createGame('np1-4-1');
    if (!initial) throw new Error('Invalid fixture');
    const nearly = { ...initial, matched: Array.from({ length: 16 }, (_, i) => i).filter((i) => i !== 0 && i !== 11),
      moves: 7, elapsedMs: 61000, started: true };
    const one = activateCard(nearly, 0);
    expect(turnAnnouncement(one, activateCard(one, 11))).toBe('Pair found. All pairs found in 8 moves and 1:01.');
  });
});

