export const BOARD_VERSION = 'np1';
export const SUPPORTED_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type BoardSize = (typeof SUPPORTED_SIZES)[number];
export const MAX_SEED = 2147483646;
export type Board = Readonly<{ code: string; size: BoardSize; seed: number }>;

export function isBoardSize(value: unknown): value is BoardSize {
  return SUPPORTED_SIZES.some((size) => size === value);
}

export function parseBoardCode(text: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9]\d*)$/.exec(text);
  if (!match || match[0] !== text) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isBoardSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code: text, size, seed });
}
import type { Board } from './boardCode.ts';

const MODULUS = 2147483647;
const GENERATOR_RANGE = MODULUS - 1;
export function parkMiller(state: number): number {
  // The largest product is below 2^53, so integer arithmetic is exact.
  return (state * 16807) % MODULUS;
}

export function generateDeck(board: Board): readonly number[] {
  const deck = Array.from({ length: board.size ** 2 }, (_, index) => Math.floor(index / 2));
  let randomState = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const bound = index + 1;
    const limit = Math.floor(GENERATOR_RANGE / bound) * bound;
    let value: number;
    do {
      randomState = parkMiller(randomState);
      value = randomState - 1;
    } while (value >= limit);
    const otherIndex = value % bound;
    const current = deck[index];
    const other = deck[otherIndex];
    if (current === undefined || other === undefined) throw new Error('Invalid deck position');
    deck[index] = other;
    deck[otherIndex] = current;
  }
  return Object.freeze(deck);
}
import { parseBoardCode } from './boardCode.ts';
import type { Board } from './boardCode.ts';
import { generateDeck } from './deck.ts';

export const SELECTION_KINDS = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export type Selection =
  | Readonly<{ kind: typeof SELECTION_KINDS.closed }>
  | Readonly<{ kind: typeof SELECTION_KINDS.one; index: number }>
  | Readonly<{ kind: typeof SELECTION_KINDS.mismatch; first: number; second: number; remainingMs: number }>;
export const CLOSED_SELECTION: Selection = Object.freeze({ kind: SELECTION_KINDS.closed });
export type GameState = Readonly<{
  board: Board;
  deck: readonly number[];
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export function createGame(boardCode: string): GameState | null {
  const board = parseBoardCode(boardCode);
  if (!board) return null;
  return {
    board, deck: generateDeck(board), matched: [], selection: CLOSED_SELECTION,
    moves: 0, elapsedMs: 0, started: false,
  };
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case 'closed': return false;
    case 'one': return state.selection.index === index;
    case 'mismatch': return state.selection.first === index || state.selection.second === index;
  }
}
import { CLOSED_SELECTION, isWon } from './state.ts';
import type { GameState } from './state.ts';

export const MISMATCH_MS = 800;
export const MAX_MOVES = 999999;

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length
    || state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case 'closed':
      return { ...state, started: true, selection: { kind: 'one', index } };
    case 'one': {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return { ...state, moves, matched: [...state.matched, first, index], selection: CLOSED_SELECTION };
      }
      return {
        ...state, moves,
        selection: { kind: 'mismatch', first, second: index, remainingMs: MISMATCH_MS },
      };
    }
    case 'mismatch': return state;
  }
}
import { CLOSED_SELECTION, isWon } from './state.ts';
import type { GameState } from './state.ts';

export const MAX_ELAPSED_MS = 359999999;

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  switch (state.selection.kind) {
    case 'closed':
    case 'one': return { ...state, elapsedMs };
    case 'mismatch': {
      const remainingMs = state.selection.remainingMs - milliseconds;
      return {
        ...state, elapsedMs,
        selection: remainingMs <= 0 ? CLOSED_SELECTION : { ...state.selection, remainingMs },
      };
    }
  }
}

export function formatTime(milliseconds: number): string {
  const seconds = Math.floor(milliseconds / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

export function isSafeInteger(value: unknown, maximum = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= maximum;
}

export function parseFormatJson(text: string, byteLimit: number): unknown {
  if (new TextEncoder().encode(text).byteLength > byteLimit) return null;
  try { return JSON.parse(text); } catch { return null; }
}
import { MAX_MOVES } from './activateCard.ts';
import { MAX_ELAPSED_MS } from './advanceGame.ts';
import { hasExactKeys, isRecord, isSafeInteger, parseFormatJson } from './formatInput.ts';
import { decodeSelection } from './snapshotSelection.ts';
import { createGame, isWon, pairCount } from './state.ts';
import type { GameState } from './state.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65536;
const SNAPSHOT_KEYS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === 'mismatch'
    ? { ...state.selection, remainingMs: Math.max(1, Math.ceil(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({
    version: SNAPSHOT_VERSION, boardCode: state.board.code, matched: state.matched,
    selection, moves: state.moves, elapsedMs: Math.floor(state.elapsedMs), started: state.started,
  }, null, 2);
}

function decodeMatched(value: unknown, state: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const entries: readonly unknown[] = value;
  const matched: number[] = [];
  const faces = new Map<number, number>();
  for (const index of entries) {
    if (!isSafeInteger(index, state.deck.length - 1) || matched.includes(index)) return null;
    const face = state.deck[index];
    if (face === undefined) return null;
    faces.set(face, (faces.get(face) ?? 0) + 1);
    matched.push(index);
  }
  return [...faces.values()].every((count) => count === 2) ? matched : null;
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseFormatJson(text, SNAPSHOT_BYTE_LIMIT);
  if (!isRecord(value) || !hasExactKeys(value, SNAPSHOT_KEYS) || value.version !== SNAPSHOT_VERSION
    || typeof value.boardCode !== 'string' || typeof value.started !== 'boolean'
    || !isSafeInteger(value.moves, MAX_MOVES) || !isSafeInteger(value.elapsedMs, MAX_ELAPSED_MS)) return null;
  const initial = createGame(value.boardCode);
  if (!initial) return null;
  const matched = decodeMatched(value.matched, initial);
  if (!matched) return null;
  const partial = { ...initial, matched };
  const selection = decodeSelection(value.selection, partial);
  if (!selection) return null;
  const state = {
    ...partial, selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started,
  };
  const requiredMoves = pairCount(state) + (selection.kind === 'mismatch' ? 1 : 0);
  if (state.moves < requiredMoves || (isWon(state) && selection.kind !== 'closed')) return null;
