import { useEffect } from 'react';

type ClockOptions = Readonly<{
  dealId: number;
  running: boolean;
  settle: (expectedDeal?: number) => void;
  setVisible: (visible: boolean) => void;
  delay: () => number;
}>;

export function useSessionClock({ dealId, running, settle, setVisible, delay }: ClockOptions): void {
  useEffect(() => {
    let disposed = false;
    let timer: number | undefined;
    function schedule() {
      if (!disposed && running && document.visibilityState !== 'hidden') {
        timer = window.setTimeout(tick, delay());
      }
    }
    function tick() {
      if (disposed) return;
      settle(dealId);
      schedule();
    }
    function onVisibility() {
      if (disposed) return;
      settle(dealId);
      setVisible(document.visibilityState !== 'hidden');
      if (timer !== undefined) window.clearTimeout(timer);
      schedule();
    }
    document.addEventListener('visibilitychange', onVisibility);
    schedule();
    return () => {
      disposed = true;
      if (timer !== undefined) window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', onVisibility);
    };
  }, [dealId, running, settle, setVisible, delay]);
}
import { useImperativeHandle, useRef, useState } from 'react';
import type { CSSProperties, KeyboardEvent, Ref } from 'react';
import { isRevealed } from '../state.ts';
import type { GameState } from '../state.ts';
import { Card } from './Card.tsx';
import { moveFocus } from './navigation.ts';
import './Board.css';

export type BoardHandle = Readonly<{ focusRemembered: () => void }>;
type BoardProps = Readonly<{
  game: GameState; paused: boolean; onActivate: (index: number) => void; ref?: Ref<BoardHandle>;
}>;
type BoardStyle = CSSProperties & Readonly<{ '--columns': number }>;

export function Board({ game, paused, onActivate, ref }: BoardProps) {
  const [tabStop, setTabStop] = useState(0);
  const board = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => ({
    focusRemembered() { board.current?.querySelector<HTMLButtonElement>('button[tabindex="0"]')?.focus(); },
  }), []);
  function focus(index: number) {
    board.current?.querySelectorAll('button').item(index)?.focus();
  }
  function keyDown(index: number, event: KeyboardEvent<HTMLButtonElement>) {
    if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
    const destination = moveFocus(index, game.board.size, event.key);
    if (destination !== null) {
      event.preventDefault();
      focus(destination);
    } else if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      onActivate(index);
    }
  }
  const style: BoardStyle = { '--columns': game.board.size };
  return <div className="board-scroll" aria-label="Card board" role="group">
    <div className="board" ref={board} style={style}>
      {game.deck.map((face, index) => <Card key={index} index={index} size={game.board.size} face={face}
        revealed={isRevealed(game, index)} matched={game.matched.includes(index)}
        blocked={paused || game.selection.kind === 'mismatch'} tabStop={index === tabStop}
        onActivate={() => onActivate(index)} onKeyDown={(event) => keyDown(index, event)}
        onFocus={(button) => {
          setTabStop(index);
          button.scrollIntoView({ block: 'nearest', inline: 'nearest' });
        }} />)}
    </div>
  </div>;
}
import type { KeyboardEvent } from 'react';
import { CardFace } from './CardFace.tsx';
import { faceIdentity } from './faceIdentity.ts';
import './Card.css';

type CardProps = Readonly<{
  index: number; size: number; face: number; revealed: boolean; matched: boolean;
  blocked: boolean; tabStop: boolean; onActivate: () => void;
  onFocus: (button: HTMLButtonElement) => void;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
}>;

export function Card({ index, size, face, revealed, matched, blocked, tabStop,
  onActivate, onFocus, onKeyDown }: CardProps) {
  const position = `Row ${Math.floor(index / size) + 1}, column ${index % size + 1}`;
  const name = revealed ? `${position}, ${faceIdentity(face).name}, ${matched ? 'matched' : 'revealed'}`
    : `${position}, closed`;
  return <button type="button" className={`card${revealed ? ' revealed' : ''}${matched ? ' matched' : ''}`}
    aria-label={name} aria-disabled={matched || blocked ? true : undefined} tabIndex={tabStop ? 0 : -1}
    onFocus={(event) => onFocus(event.currentTarget)} onKeyDown={onKeyDown}
    onClick={(event) => {
      if (event.button !== 0 || (event.detail === 0
        && (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey))) return;
      onActivate();
    }}>
    {revealed ? <CardFace id={face} /> : <span className="card-back" aria-hidden="true">◇</span>}
    {matched && <span className="card-check" aria-hidden="true">✓</span>}
  </button>;
}
import { MAX_MOVES } from '../activateCard.ts';
import { isBoardSize, SUPPORTED_SIZES } from '../boardCode.ts';
import type { BoardSize } from '../boardCode.ts';
import { isRecord, isSafeInteger } from '../formatInput.ts';

export const PREFERENCES_KEY = 'neon-pairs.preferences.v1';
export type BestScores = Readonly<Partial<Record<BoardSize, number>>>;
export type Preferences = Readonly<{ size: BoardSize; best: BestScores }>;
export type PreferenceStorage = Pick<Storage, 'getItem' | 'setItem'>;

function browserStorage(): PreferenceStorage | null {
  try { return window.localStorage; } catch { return null; }
}

export function readPreferences(storage = browserStorage()): Preferences {
  const fallback: Preferences = { size: 4, best: {} };
  try {
    const text = storage?.getItem(PREFERENCES_KEY);
    if (!text) return fallback;
    const value: unknown = JSON.parse(text);
    if (!isRecord(value)) return fallback;
    const best: Partial<Record<BoardSize, number>> = {};
    if (isRecord(value.best)) {
      for (const size of SUPPORTED_SIZES) {
        const score = value.best[String(size)];
        if (isSafeInteger(score, MAX_MOVES)) best[size] = score;
      }
    }
    return { size: isBoardSize(value.size) ? value.size : 4, best };
  } catch { return fallback; }
}

export function writePreferences(value: Preferences, storage = browserStorage()): void {
  try { storage?.setItem(PREFERENCES_KEY, JSON.stringify(value)); } catch { /* Play stays in memory. */ }
}
import { MAX_SEED } from '../boardCode.ts';
import type { BoardSize } from '../boardCode.ts';
import { createGame } from '../state.ts';
import type { GameState } from '../state.ts';

export function newDeal(size: BoardSize, previousCode?: string): GameState {
  const random = new Uint32Array(1);
  let value: number;
  if (globalThis.crypto?.getRandomValues) {
    globalThis.crypto.getRandomValues(random);
    value = random[0] ?? 0;
  } else value = Math.floor(Math.random() * MAX_SEED);
  let seed = value % MAX_SEED + 1;
  if (`np1-${size}-${seed}` === previousCode) seed = seed % MAX_SEED + 1;
  const game = createGame(`np1-${size}-${seed}`);
  if (!game) throw new Error('Unable to create supported deal');
  return game;
}
